<template>
  <div class="gs-backdrop" @click.self="$emit('close')" @keydown="dialogKeys">
    <section ref="dialog" class="gs-dialog" role="dialog" aria-modal="true" aria-labelledby="gs-title">
      <header class="gs-header">
        <div class="gs-title-group"><span class="gs-title-icon"><GraphIcon name="graph"/></span><h2 id="gs-title">本体结构</h2></div>
        <div class="gs-summary" aria-label="图谱规模"><div><span>实体类型</span><b>{{schema.nodes.length}}</b></div><div><span>节点</span><b>{{format(repository.nodes.length)}}</b></div><div><span>关系组合</span><b>{{schema.edges.length}}</b></div><div><span>关系</span><b>{{format(repository.edges.length)}}</b></div></div>
        <button ref="closeButton" class="gs-icon gs-close" aria-label="关闭本体结构" @click="$emit('close')"><GraphIcon name="close"/></button>
      </header>
      <div class="gs-type-filter" aria-label="按实体类型筛选关系"><button :class="{active:!selectedType}" @click="selectType('')">全部类型</button><button v-for="row in schema.nodes" :key="row.type" :class="{active:selectedType===row.type}" :aria-pressed="selectedType===row.type" @click="selectType(row.type)"><i :style="{background:color(row.type)}"></i>{{row.type}}<span>{{format(row.count)}}</span></button></div>
      <div class="gs-toolbar"><div class="gs-tabs" role="group" aria-label="本体结构视图"><button :class="{active:tab==='graph'}" @click="tab='graph'"><GraphIcon name="graph"/>结构图</button><button :class="{active:tab==='table'}" @click="tab='table'">关系明细</button></div><label class="gs-search"><GraphIcon name="search"/><input v-model="query" aria-label="搜索本体关系" placeholder="搜索类型或关系名称"></label></div>
      <div class="gs-content" :class="{'gs-table-mode':tab==='table'}">
        <div v-show="tab==='graph'" class="gs-map"><div ref="canvas" class="gs-render" role="img" aria-label="实体类型关系图"></div><div v-if="error" role="alert" class="gs-error">{{error}}<button @click="renderGraph">重试</button></div><div class="gs-tools"><button v-for="tool in tools" :key="tool.action" class="gs-icon" :aria-label="tool.label" :title="tool.label" @click="operate(tool.action)"><GraphIcon :name="tool.icon"/></button></div></div>
        <div v-if="tab==='table'" class="gs-table-wrap"><table><colgroup><col><col><col><col class="gs-number-col"></colgroup><thead><tr><th>起点类型</th><th>关系名称</th><th>终点类型</th><th class="gs-number">关系数量</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{chosen:selectedRelation===row.id}" @click="selectRelation(row)"><td><span class="gs-table-type"><i :style="{background:color(row.source)}"></i>{{row.source}}</span></td><td><button class="gs-table-link" @click.stop="selectRelation(row)">{{row.type}} <span>→</span></button></td><td><span class="gs-table-type"><i :style="{background:color(row.target)}"></i>{{row.target}}</span></td><td class="gs-number">{{format(row.count)}}</td></tr></tbody></table><p v-if="!rows.length" class="gs-empty">暂无匹配关系，试试其他关键词。</p></div>
        <aside class="gs-details" aria-label="本体关系详情">
          <div class="gs-details-heading"><h3>{{selectedType||'关系概览'}}</h3><button v-if="selectedType" class="gs-text" @click="selectType('')">清除筛选</button><span v-else class="gs-count-badge">{{rows.length}}</span></div>
          <div v-if="selectedType" class="gs-type-stat"><i :style="{background:color(selectedType)+'18',color:color(selectedType)}"><GraphIcon :name="selectedType"/></i><div><b>{{format(schema.nodes.find(n=>n.type===selectedType)?.count||0)}}</b><span>个节点</span></div><button class="gs-text" @click="$emit('browse',selectedType)">查看对象 ›</button></div>
          <div class="gs-list-label"><span>关联关系<small v-if="selectedType">{{rows.length}}</small></span><span>数量</span></div>
          <div class="gs-relations"><button v-for="row in rows" :key="row.id" :aria-pressed="selectedRelation===row.id" :title="`${row.source} —${row.type}→ ${row.target} · ${format(row.count)} 条`" :class="{selected:selectedRelation===row.id}" @click="selectRelation(row)"><span class="gs-relation-nodes"><i :style="{background:color(row.source)}"></i><span class="gs-node-name">{{row.source}}</span><span class="gs-relation-name">{{row.type}}<span class="gs-arrow">→</span></span><i :style="{background:color(row.target)}"></i><span class="gs-node-name">{{row.target}}</span></span><strong>{{format(row.count)}}</strong></button><p v-if="!rows.length" class="gs-empty">暂无匹配关系</p></div>
          <div v-if="relation" class="gs-selection" role="status"><div class="gs-selection-heading"><span>关系详情</span><button class="gs-selection-close" aria-label="关闭关系详情" @click="selectedRelation='';highlight()"><GraphIcon name="close"/></button></div><b>{{relation.source}}<span>→</span>{{relation.target}}</b><dl><dt>关系名称</dt><dd>{{relation.type}}</dd><dt>关系数量</dt><dd>{{format(relation.count)}} 条</dd></dl></div>
        </aside>
      </div>

    </section>
  </div>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import GraphIcon from './GraphIcon.vue'
import {typeColor} from './graphColorSettings.js'
const props=defineProps({repository:{type:Object,required:true},colorSettings:{type:Object,required:true}})
const emit=defineEmits(['close','browse'])
const dialog=ref(),closeButton=ref(),canvas=ref(),selectedType=ref(''),selectedRelation=ref(''),query=ref(''),tab=ref('graph'),error=ref('')
const schema=computed(()=>{const data=props.repository.schema();return {...data,edges:data.edges.map((row,index)=>({...row,id:`schema-relation-${index}`}))}})
const rows=computed(()=>{const terms=query.value.trim().toLowerCase().split(/\s+/).filter(Boolean);return schema.value.edges.filter(row=>(!selectedType.value||row.source===selectedType.value||row.target===selectedType.value)&&terms.every(term=>`${row.source} ${row.type} ${row.target}`.toLowerCase().includes(term)))})
const relation=computed(()=>schema.value.edges.find(row=>row.id===selectedRelation.value))
const format=value=>Number(value).toLocaleString('zh-CN'),color=type=>typeColor(type,props.colorSettings)
const tools=[{action:'in',label:'放大结构图',icon:'zoomIn'},{action:'out',label:'缩小结构图',icon:'zoomOut'},{action:'fit',label:'适应结构图',icon:'fit'}]
let graph,observer,disposed=false,resizeTimer,rendering=false
function selectType(type){selectedType.value=type;selectedRelation.value='';highlight()}
function selectRelation(row){selectedRelation.value=row.id;highlight()}
function highlight(){
  if(!graph||rendering||disposed)return
  const visible=new Set(rows.value.map(row=>row.id)),states={}
  for(const node of schema.value.nodes){const connected=rows.value.some(row=>row.source===node.type||row.target===node.type);states[node.type]=selectedType.value===node.type?['selected']:connected?[]:['dim']}
  for(const row of schema.value.edges)states[row.id]=selectedRelation.value===row.id?['selected']:visible.has(row.id)?[]:['dim']
  graph.setElementState(states,false).catch(()=>{})
}
async function renderGraph(){
  if(rendering||disposed||tab.value!=='graph')return
  rendering=true
  try{
    error.value='';await nextTick()
    const {Graph}=await import('@antv/g6');if(disposed)return
    if(!graph){
      graph=new Graph({container:canvas.value,width:canvas.value.clientWidth,height:canvas.value.clientHeight,animation:false,padding:[38,35,55,45],zoomRange:[.35,3],behaviors:['drag-canvas','zoom-canvas','drag-element'],node:{type:'circle',state:{selected:{lineWidth:3,stroke:'#333333',halo:true,haloStroke:'#e8e8e8',haloLineWidth:5,haloStrokeOpacity:.5},dim:{opacity:.3}}},edge:{type:'quadratic',state:{selected:{stroke:'#333333',lineWidth:2.5,labelFill:'#292929'},dim:{opacity:.1}}}})
      graph.on('node:click',event=>selectType(event.target.id))
      graph.on('edge:click',event=>selectRelation(schema.value.edges.find(row=>row.id===event.target.id)))
      graph.on('canvas:click',()=>selectType(''))
    }
    const places={事件:[65,-95],传导规则:[235,-95],驱动因素:[405,-95],需求变化:[575,-95],业务行动:[745,-95],行业:[65,60],行业工厂:[65,205],品类:[225,325],企业:[225,110],指标值:[415,205],地点:[545,55],时间:[645,325],因素指标:[415,365]}
    const nodes=schema.value.nodes.map((row,index)=>{const [x,y]=places[row.type]||[100+index%3*220,90+Math.floor(index/3)*180];return {id:row.type,style:{x,y,size:55,opacity:1,fill:color(row.type),stroke:'#fff',lineWidth:2,label:true,labelText:`${row.type}\n${format(row.count)} 个`,labelPlacement:'bottom',labelOffsetY:9,labelFontSize:13,labelLineHeight:20,labelFill:'#292929',labelFontWeight:500,cursor:'pointer'}}})
    const edges=schema.value.edges.map(row=>({id:row.id,source:row.source,target:row.target,style:{opacity:1,stroke:'#a8b6ca',lineWidth:1.2,endArrow:true,endArrowSize:6,curveOffset:row.source==='企业'&&row.target==='品类'?18:0,loopPlacement:['企业','品类'].includes(row.source)?'left':row.source==='时间'?'right':'top',loopDist:42,label:true,labelText:row.type,labelPlacement:['包含','属于'].includes(row.type)?.7:.5,labelFontSize:12,labelFill:'#686868',labelAutoRotate:false,labelBackground:true,labelBackgroundFill:'#fff',labelPadding:[3,5],cursor:'pointer'}}))
    graph.setData({nodes,edges});await graph.render();await graph.fitView({when:'always'},false)
  }catch(e){if(!disposed)error.value='结构图加载失败：'+e.message}
  finally{rendering=false;highlight()}
}
async function operate(action){if(!graph)return;try{if(action==='fit')await graph.fitView({when:'always'},false);else await graph.zoomBy(action==='in'?1.2:1/1.2,false)}catch{}}
function dialogKeys(event){
  if(event.key==='Escape'){event.stopPropagation();emit('close');return}
  if(event.key!=='Tab')return
  const controls=[...dialog.value.querySelectorAll('button,input,[tabindex="0"]')].filter(node=>!node.disabled&&node.getClientRects().length)
  const first=controls[0],last=controls.at(-1)
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}
}
watch([selectedType,query],()=>{if(!rows.value.some(row=>row.id===selectedRelation.value))selectedRelation.value='';highlight()})
watch(tab,async value=>{await nextTick();if(value==='graph'){if(!graph)await renderGraph();else{graph.resize();await graph.fitView({when:'always'},false)}}})
onMounted(async()=>{closeButton.value?.focus();await renderGraph();if(disposed)return;observer=new ResizeObserver(()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(graph&&!disposed&&tab.value==='graph'){graph.resize();graph.fitView({when:'always'},false)}},100)});observer.observe(canvas.value)})
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();clearTimeout(resizeTimer);graph?.destroy()})
</script>
